SP=sys.argv[1]
h=json.load(open(SP+'/hist.json'))
commits=h['commits']
rowre=re.compile(r'^\| (\d+) \|')
snaps=[]
for i,(H,hh,d,a,s) in enumerate(commits):
    txt=subprocess.check_output(['git','show',f'{H}:explorations/fortress-gap-ledger.md'],text=True,errors='replace')
    cur={}
    for l in txt.split('\n'):
        if l.startswith('## Revival worklist') or l.startswith('## Counts'): break
        m=rowre.match(l)
        if m:
            parts=re.split(r'(?<!\\)\|',l.strip()[1:])
            cur[int(m.group(1))]=dict(claim=parts[1].strip() if len(parts)>1 else '',status=parts[2].strip() if len(parts)>2 else '',len=len(l),text=l)
    snaps.append(cur)
import pickle
pickle.dump(snaps,open(SP+'/snaps.pkl','wb'))
# detect disappearances and replacement
events=[]
for i in range(1,len(snaps)):
    a,b=snaps[i-1],snaps[i]
    for n in a:
        if n not in b: events.append(('GONE',n,i,commits[i][1]))
    for n in b:
        if n in a:
            r=difflib.SequenceMatcher(None,a[n]['claim'][:300],b[n]['claim'][:300]).ratio()
            if r<0.6: events.append(('CLAIMCHG',n,i,commits[i][1],round(r,2)))
for e in events: print(e)
EOF
