import json,re,collections,itertools,sys,math
SP=sys.argv[1]
rows=json.load(open(SP+'/rows3.json'))
R={r['num']:r for r in rows}
# text vectors over claim
def toks(s):
    s=re.sub(r'[`*\\]','',s.lower())
    return re.findall(r'[a-z0-9_\.\[\]\-]+',s)
docs={}
for r in rows:
    t=toks(r['claim'])
    grams=t+[a+' '+b for a,b in zip(t,t[1:])]
    docs[r['num']]=collections.Counter(grams)
df=collections.Counter()
for d in docs.values():
    for g in d: df[g]+=1
N=len(docs)
vec={}
for n,d in docs.items():
    v={g:(1+math.log(c))*math.log(N/df[g]) for g,c in d.items() if df[g]<N*0.2}
    norm=math.sqrt(sum(x*x for x in v.values())) or 1
    vec[n]={g:x/norm for g,x in v.items()}
def cos(a,b):
    if len(vec[a])>len(vec[b]): a,b=b,a
    return sum(x*vec[b].get(g,0) for g,x in vec[a].items())
nums=sorted(R)
sim={}
for a,b in itertools.combinations(nums,2):
    c=cos(a,b)
    if c>=0.3: sim[(a,b)]=c
print('pairs cos>=0.3',len(sim),'>=0.4',sum(1 for c in sim.values() if c>=0.4),'>=0.5',sum(1 for c in sim.values() if c>=0.5),'>=0.6',sum(1 for c in sim.values() if c>=0.6),'>=0.7',sum(1 for c in sim.values() if c>=0.7))
cit=json.load(open(SP+'/cites.json'))
CODE=('.fss','.fsi','.java','.scala','.rats','.ast')
def codecites(n):
    return set(tuple(c) for c in cit[str(n)]['cites'] if c[0].endswith(CODE))
def speccites(n):
    return set(tuple(c) for c in cit[str(n)]['cites'] if c[0].endswith('.tex'))
# probe/test names from reproducer cell
def probes(n):
    return set(re.findall(r'\b([A-Za-z0-9_\-]+\.(?:fss|test))\b',R[n]['repro']))
pairs=collections.defaultdict(dict)
for a,b in itertools.combinations(nums,2):
    s={}
    cc=codecites(a)&codecites(b)
    if cc: s['code']=sorted(cc)
    sc=speccites(a)&speccites(b)
    if sc: s['spec']=sorted(sc)
    pr=probes(a)&probes(b)
    if pr: s['probe']=sorted(pr)
    if (a,b) in sim: s['cos']=round(sim[(a,b)],2)
    if s: pairs[(a,b)]=s
json.dump({f'{a},{b}':v for (a,b),v in pairs.items()},open(SP+'/pairs.json','w'))
sig=collections.Counter()
for k,v in pairs.items():
    for s in v: sig[s]+=1
print(sig)
print('pairs total with any signal',len(pairs))
EOF
